package user

import (
  "testing"

  "github.com/stretchr/testify/assert"
)

func TestFindByEmail(t *testing.T) {
  repo := newTestRepo(t)

  u, err := repo.FindByEmail("alice@example.com")
  assert.NoError(t, err)
  assert.Equal(t, "Alice", u.Name)
  assert.Equal(t, "pro", u.Plan)
}

